  function paymentSummary(group){const rows=uniqueOrders(group),methods=new Map();let collected=0,value=0;for(const o of rows){value+=summaryOrderValue(o);const amount=Number(o.amountCollected||0);collected+=amount;if(amount>0){const key=String(o.paymentMethod||'غير محدد').trim()||'غير محدد';const x=methods.get(key)||{name:key,count:0,amount:0};x.count++;x.amount+=amount;methods.set(key,x)}}return {value,collected,remaining:Math.max(0,value-collected),rate:value?Math.min(100,collected/value*100):0,methods:[...methods.values()].sort((a,b)=>b.amount-a.amount)}}
